# ---------------------------------------------------------------- assemble
NS = {">": {"≥", r"\geq", r"\geqslant", ">=", r"\ge"}, "<": {"≤", r"\leq", r"\leqslant", "<=", r"\le"}}
NE = {"≠", r"\neq", r"\ne"}
nb = lambda v: re.sub(r"[\s$]", "", str(v or ""))
c.execute("SELECT id, correct_answer_latex, distractor_meta, source_reference FROM tasks_master WHERE is_active")
P = {}
for tid, k, d, src in c.fetchall():
    m = M.get(tid, {}); key = nb(m.get("k", k))
    cmp = key in ("<", ">", "=")
    if tid not in M and tid not in J and not cmp: continue
    d = d or []; whys = [m["why"]] if m.get("why") else []
    bad = set(J.get(tid, {}).get("drop", []))
    if tid == "G10_TB_§10_9_53_6": bad.add(0)
    if bad: whys.append(JUNKWHY)
    ns = set()
    if cmp:
        for i, x in enumerate(d):
            v = nb(x.get("value"))
            if (key in NS and v in NS[key]) or (key == "=" and (v in NS[">"] | NS["<"])) or (key in "<>" and v in NE): ns.add(i)
        if ns: whys.append("нестрогий знак / «≠» при верном строгом ответе — тоже верное утверждение (правильный ответ в другой форме) — закрыт")
    bad |= ns
    bad -= set(m.get("dnew", {})); bad -= set(m.get("drop", []))
    dnew = dict(m.get("dnew", {})); drop = list(m.get("drop", []))
    if cmp and bad:
        present = {nb(x.get("value")) for i, x in enumerate(d) if i not in bad and i not in drop} | {nb(v) for v, _ in dnew.values()}
        miss = [s for s in "<>=" if s != key and s not in present]
        if m.get("oldkey") and m["oldkey"] in miss: miss.remove(m["oldkey"]); miss.insert(0, m["oldkey"])
        for i in sorted(bad):
            if miss:
                s = miss.pop(0); dnew[i] = (S(s), ("прежний неверный ключ" if s == m.get("oldkey") else "неверный знак сравнения") + " (вместо закрытого варианта)")
            else: drop.append(i)
    else: drop += sorted(bad)
    if not (dnew or drop or "k" in m or "q" in m or "qrep" in m): continue
    e = {"why": " ; ".join(whys) or "—", "src": "самопроверка выборки Виленкин 5 → класс «сравнение / знак действия», сверено: " + SRC.get(src[:8], src[:8]) + ", 26.09"}
    for f in ("k", "q", "qrep"):
        if f in m: e[f] = m[f]
    if dnew: e["dnew"] = {i: list(v) for i, v in dnew.items()}
    if drop: e["drop"] = sorted(set(drop))
    if m.get("oldkey") and m["oldkey"] not in [nb(v) for v, _ in dnew.values()] and m["oldkey"] not in [nb(x.get("value")) for x in d]:
        e["dadd"] = [(S(m["oldkey"]), "прежний неверный ключ")]
    P[tid] = e
json.dump(P, open("/audit/v5b_P.json", "w"), ensure_ascii=False, indent=1)
missing = [t for t in M if t not in P]; print("tasks", len(P), "manual not emitted:", missing)
